class PriceCalculator
{
    public function __construct(
        private readonly DiscountService $discounts,
        private readonly TaxService $taxes,
        private readonly ShippingService $shipping,
    ) {
    }

    public function compute(Order $order): Money
    {
        $subtotal = $order->subtotal;                       // magic accessor
        $discount = $this->discounts->discountFor($order, $subtotal);
        $taxable = $subtotal->subtract($discount);

        $tax = $this->taxes->taxFor($order, $taxable);
        $shipping = $this->shipping->shippingFor($order, $taxable);

        return $taxable->add($tax)->add($shipping);
    }

    /** Returns the discounted amount before tax and shipping. */
    public function taxableBase(Order $order): Money
    {
        $subtotal = $order->subtotal;

        return $subtotal->subtract($this->discounts->discountFor($order, $subtotal));
    }
}

class Order extends Model
{
    use HasFactory;

    protected $fillable = ['customer_id', 'status', 'coupon_code', 'shipping_country'];

    public function customer(): BelongsTo
    {
        return $this->belongsTo(Customer::class);
    }

    public function lines(): HasMany
    {
        return $this->hasMany(OrderLine::class);
    }

    public function coupon(): BelongsTo
    {
        // Resolved by string column, not by id — the coupon_code magic attribute.
        return $this->belongsTo(Coupon::class, 'coupon_code', 'code');
    }

    /**
     * Accessor exposed as $order->subtotal. Sums the order lines. Because this is
     * a magic accessor, callers reference a property the analyzer cannot see.
     */
    public function getSubtotalAttribute(): Money
    {
        return $this->lines->reduce(
            fn (Money $carry, OrderLine $line) => $carry->add($line->lineTotal()),
            Money::zero(),
        );
    }

    public function lineCount(): int
    {
        return $this->lines->count();
    }
}

public function test_final_price_applies_discount_before_tax(): void
{
    config(['shop.free_shipping_threshold' => 75.00, 'shop.shipping_rates' => ['ES' => 490]]);

    $customer = Customer::factory()->create(['loyalty_tier' => 'gold', 'country' => 'ES']);
    $widget = Product::factory()->create(['price_cents' => 1500]);
    $gadget = Product::factory()->create(['price_cents' => 3200]);

    $order = Order::factory()->create([
        'customer_id' => $customer->id,
        'shipping_country' => 'ES',
    ]);
    $order->lines()->create(['product_id' => $widget->id, 'quantity' => 2, 'unit_price_cents' => 1500]);
    $order->lines()->create(['product_id' => $gadget->id, 'quantity' => 1, 'unit_price_cents' => 3200]);
    $order->refresh();

    $total = Pricing::compute($order);

    $this->assertSame(7242, $total->cents);
    $this->assertEqualsWithDelta(72.42, $total->amount(), 0.001);
}

